// BD Situation Intelligence: one footer for the sign-in page, the dashboard and the legal pages.
// public/*.html legal pages are generated by brand/legal/build.py with the same links and text.

export const SITE_OPERATOR = 'The Asia Times Company Ltd';
export const SITE_CONTACT_EMAIL = 'contact@bdnews.si';

export const SITE_FOOTER_LINKS: ReadonlyArray<{ href: string; label: string; rel?: string }> = [
  { href: '/about.html', label: 'About' },
  { href: '/privacy.html', label: 'Privacy Policy' },
  { href: '/terms.html', label: 'Terms of Service' },
  { href: '/copyright.html', label: 'Copyright' },
  { href: 'https://github.com/imonitsc/bdnews-si', label: 'Source code (AGPL-3.0)', rel: 'noopener' },
];

/** Static, trusted footer markup (no user input). */
export function siteFooterHtml(year: number = new Date().getFullYear()): string {
  const links = SITE_FOOTER_LINKS.map((l) => {
    const ext = l.href.startsWith('http') ? ` target="_blank" rel="${l.rel ?? 'noopener'}"` : '';
    return `<a href="${l.href}"${ext}>${l.label}</a>`;
  }).join(' · ');
  return `<span class="bdsi-footer-copy">© ${year} ${SITE_OPERATOR} · BD Situation Intelligence</span><span class="bdsi-footer-links">${links}</span>`;
}
